"""Helper functions for the MD System Builder GUI tab."""from __future__ import annotationsfrom pathlib import Pathdef get_available_built_polymers(    structure_database: str | Path = "structure_database",) -> list[str]:    """    Return the names of all built PHA polymers.    Built polymers are expected inside:        structure_database/built_PHAs/<polymer_name>/    """    structure_database = Path(structure_database)    built_polymers_dir = structure_database / "built_PHAs"    if not built_polymers_dir.exists():        return []    polymer_names = [        directory.name        for directory in built_polymers_dir.iterdir()        if directory.is_dir()    ]    return sorted(polymer_names)